UPDATE cal_events SET cube_mode = 'set', cube_id = own_cubes.id
FROM picked JOIN own_cubes ON own_cubes.name = picked.cube
WHERE cal_events.is_sample = 1 AND cal_events.date = picked.day AND cal_events.start_time = picked.start_time;

-- A vote under way on the next four Sundays: three suggested Cubes for each
-- open draft, with who suggested each one and who can bring it. The seat keeps
-- the Cubes in the order they were suggested, which is how a tie is settled.
WITH own_cubes(name, id) AS (SELECT name, MIN(id) FROM cubes WHERE owner = 'Levi Wilson' AND status = 'approved' GROUP BY name),
  suggested(day, start_time, seat, cube, suggester, bringer) AS (VALUES
    ('2026-11-29', '13:00', 1, 'Mono Blue', 'Sample Ann', 'Sample Ann'),
    ('2026-11-29', '13:00', 2, 'MTGO Vintage Cube', 'Sample Ben', NULL),
    ('2026-11-29', '13:00', 3, 'Abecedarian Cube - 1st Draft for New Mages', 'Sample Cal', 'Sample Dee'),
    ('2026-12-06', '13:00', 1, 'MTGO Vintage Cube', 'Sample Ann', 'Sample Ben'),
    ('2026-12-06', '13:00', 2, 'Levi''s Commander Cube #1', 'Sample Ben', 'Sample Cal'),
    ('2026-12-06', '13:00', 3, 'Mono Blue', 'Sample Cal', NULL),
    ('2026-12-13', '13:00', 1, 'Abecedarian Cube - 1st Draft for New Mages', 'Sample Ann', NULL),
    ('2026-12-13', '13:00', 2, 'Mono Blue', 'Sample Ben', 'Sample Cal'),
    ('2026-12-13', '13:00', 3, 'Levi''s Commander Cube #1', 'Sample Cal', NULL),
    ('2026-12-20', '13:00', 1, 'Levi''s Commander Cube #1', 'Sample Ann', 'Sample Ann'),
    ('2026-12-20', '13:00', 2, 'MTGO Vintage Cube', 'Sample Ben', NULL),
    ('2026-12-20', '13:00', 3, 'Abecedarian Cube - 1st Draft for New Mages', 'Sample Cal', NULL))
SELECT e.id, own_cubes.id, s.id, b.id, e.created_at
FROM suggested
JOIN cal_events e ON e.is_sample = 1 AND e.date = suggested.day AND e.start_time = suggested.start_time AND e.cube_mode = 'vote'
JOIN own_cubes ON own_cubes.name = suggested.cube
LEFT JOIN cal_attendees s ON s.event_id = e.id AND s.name = suggested.suggester
LEFT JOIN cal_attendees b ON b.event_id = e.id AND b.name = suggested.bringer
ORDER BY e.id, suggested.seat;

