    ('2026-12-13', '13:00', 'Sample Cal', 'Abecedarian Cube - 1st Draft for New Mages', 'Levi''s Commander Cube #1', 'Mono Blue'),
    ('2026-12-13', '13:00', 'Sample Dee', 'Mono Blue', 'Levi''s Commander Cube #1', 'Abecedarian Cube - 1st Draft for New Mages'),
    ('2026-12-20', '13:00', 'Sample Ann', 'MTGO Vintage Cube', 'Levi''s Commander Cube #1', 'Abecedarian Cube - 1st Draft for New Mages'),
    ('2026-12-20', '13:00', 'Sample Ben', 'MTGO Vintage Cube', 'Abecedarian Cube - 1st Draft for New Mages', 'Levi''s Commander Cube #1'))
SELECT e.id, a.id, json_array(c1.id, c2.id, c3.id), e.created_at
FROM ballot
JOIN cal_events e ON e.is_sample = 1 AND e.date = ballot.day AND e.start_time = ballot.start_time AND e.cube_mode = 'vote'
JOIN cal_attendees a ON a.event_id = e.id AND a.name = ballot.voter
JOIN own_cubes c1 ON c1.name = ballot.choice_1
JOIN own_cubes c2 ON c2.name = ballot.choice_2
JOIN own_cubes c3 ON c3.name = ballot.choice_3
ORDER BY e.id, a.id;
